            if c == sc:
                continue
            rr, cc = r % sr, c % sc
            if (r // sr) % 2:
                rr = sr - 1 - rr
            if (c // sc) % 2:
                cc = sc - 1 - cc
            out[r][c] = tile[rr][cc]
    return out
